const event = $input.first().json.body;
const message = event?.payload;
// One entry per person: their verified phone (@c.us) and WhatsApp (@lid) IDs share one set of actions.
const ALL = ['create_task', 'save_idea', 'post_progress'];
const people = [
  { ids: ['6287729072000@c.us', '108121657733360@lid'], actions: ALL },
  { ids: ['6289637394871@c.us', '37787222962251@lid'], actions: ALL },
  { ids: ['34665845742@c.us', '197048888459509@lid'], actions: ALL },
  { ids: ['15854063775@c.us', '242257764601986@lid'], actions: ALL },
  { ids: ['6281510174878@c.us', '22652362195020@lid'], actions: ALL },
  { ids: ['6282113099490@c.us', '104419446239310@lid'], actions: ALL },
  { ids: ['6281264322144@c.us', '88042584932494@lid'], actions: ALL },
  { ids: ['19173408218@c.us', '25683971563589@lid'], actions: ALL },
  { ids: ['34610210629@c.us', '223837035737316@lid'], actions: ALL },
  { ids: ['5214777041441@c.us', '223209534263432@lid'], actions: ALL },
  { ids: ['6281994770520@c.us', '269663984431135@lid'], actions: ALL },
  { ids: ['6282359361110@c.us', '55692958392522@lid'], actions: ALL },
  { ids: ['6285161912580@c.us', '174440465862739@lid'], actions: ALL },
];
if (event?.event !== 'message' || event.session !== 'default' || !message) return [{ json: { ignored: true } }];
// In a group, `from` is the group and the sender is `participant`. Groups accept prefix commands only and reply to the sender privately.
const group = typeof message.from === 'string' && message.from.endsWith('@g.us');
const sender = group ? (message.participant ?? message.author) : message.from;
const person = people.find(({ ids }) => ids.includes(sender));
if (!person || message.fromMe !== false) return [{ json: { ignored: true } }];
const messageKey = typeof message.id === 'string' && (group
  ? /^false_[^_]+@g\.us_([a-zA-Z0-9-]{8,128})(?:_[^_]+)?$/
  : /^false_.+_([a-zA-Z0-9-]{8,128})$/).exec(message.id);
if (!messageKey) return [{ json: { ignored: true } }];
const CONTROL = /^(yes|y|ya|iya|ok|oke|okay|confirm|no|n|tidak|nggak|gak|cancel|batal|retry)(?:\s+([a-f0-9]{6,32}))?[.!]?$/i;
// WhatsApp formatting (*bold*, _italic_, ~strike~) around a prefix must not hide it.
const PREFIX = /^\s*(?:task|idea|progress)\s*:/i;
// #adf anywhere sends the request to the Ama Da Flow list; the tag itself is dropped.
const ADF = /(^|\s)#adf\b/gi;
// These never reach Ama Da Flow: #adf is dropped, and their messages in Ama Da Flow groups are ignored.
const NO_ADF_GROUPS = ["120363411982534587@g.us"]; // CLICKUP_NO_ADF_GROUPS
const NO_ADF_PEOPLE = ["6281264322144@c.us", "88042584932494@lid"]; // people.json noAdf
const noAdf = NO_ADF_PEOPLE.includes(sender) || NO_ADF_GROUPS.includes(message.from);
const adf = !noAdf && typeof message.body === 'string' && /(^|\s)#adf\b/i.test(message.body);
// WAHA sends every message to both workflows. Ama Da Flow takes its groups and #adf from any chat; Dotcross takes the rest.
const ROUTE = 'dotcross';
const ADF_GROUPS = ["120363409008389144@g.us", "120363415330600046@g.us", "120363423006787416@g.us", "120363423192516390@g.us"]; // groups.json entries for list 1100380000193567
if (noAdf && group && ADF_GROUPS.includes(message.from)) return [{ json: { ignored: true } }];
if ((adf || (group && ADF_GROUPS.includes(message.from))) !== (ROUTE === 'adf')) return [{ json: { ignored: true } }];
const body = typeof message.body !== 'string' ? '' : message.body.replace(ADF, '$1').trim()
  .replace(/^([*_~]+)(\s*(?:task|idea|progress)\s*:[^\n]*?)\1(?=\n|$)/i, '$2')
  .replace(/^[*_~]+(?=\s*(?:task|idea|progress)\s*:)/i, '')
  .replace(/^(\s*(?:task|idea|progress)\s*:)[*_~]+/i, '$1');
if (group && (message.hasMedia !== false || typeof message.body !== 'string' || !(PREFIX.test(body) || CONTROL.test(body)))) return [{ json: { ignored: true } }];

const base = { chatId: sender, ...(group ? { replyTo: message.from } : {}), reference: 'WAHA pilot message ' + messageKey[1], allowedActions: person.actions, ...(adf ? { workspace: 'adf' } : {}) };
if (message.hasMedia === true && /^audio\//i.test(message.media?.mimetype ?? '')) {
  return [{ json: { ...base, messageId: message.id } }];
}
if (message.hasMedia !== false || typeof message.body !== 'string') return [{ json: { ignored: true } }];
const command = (action, fields) => person.actions.includes(action)
  ? [{ json: { ...base, action, ...fields } }]
  : [{ json: { ...base, action: 'clarify', replyText: 'That action is not enabled for you in this pilot.' } }];
const control = CONTROL.exec(body);
if (control) {
  const word = control[1].toLowerCase();
  const action = word === 'retry' ? 'retry' : 'confirm';
  const answer = /^(no|n|tidak|nggak|gak|cancel|batal)$/.test(word) ? 'no' : 'yes';
  return [{ json: { ...base, action, answer, code: control[2]?.toLowerCase() ?? '' } }];
}
const idea = /^idea\s*:([\s\S]*)$/i.exec(body);
if (idea) {
  const text = idea[1].trim();
  if (!text || text.length > 1000) return [{ json: { ...base, action: 'clarify', replyText: 'Send idea: followed by a short idea to save.' } }];
  return command('save_idea', { title: [...text].slice(0, 200).join('').replace(/\s+/g, ' '), description: text, tags: ['idea'] });
}
if (/^\s*task\s*:/i.test(body)) {
  const text = body.replace(/^\s*task\s*:/i, '');
  const assignees = [...text.matchAll(/@([\p{L}\p{N}._-]+)/gu)].map((m) => m[1]);
  // The first line is the title; any further lines (links, notes) become the description.
  const [first, ...rest] = text.replace(/@[\p{L}\p{N}._-]+/gu, ' ').trim().split('\n');
  const title = first.replace(/^[\s*_~]+|[\s*_~]+$/g, '').replace(/\s+/g, ' ');
  if (!title || title.length > 200) return [{ json: { ignored: true } }];
  const description = rest.join('\n').trim().slice(0, 2000);
  return command('create_task', { title, tags: [], assignees, ...(description ? { description } : {}) });
}
const progress = /^progress\s*:([\s\S]*)$/i.exec(body);
if (progress) {
  const text = progress[1].trim();
  if (!text || text.length > 1200) return [{ json: { ignored: true } }];
  const [, ref, update] = /^(\S+)\s+([\s\S]+)$/.exec(text) ?? [];
  const isTaskRef = ref && (/app\.clickup\.com\/t\//i.test(ref) || (/^#?[a-z0-9]{5,15}$/i.test(ref) && /\d/.test(ref)));
  // Without a link or ID the text starts with the task name; the resolver splits it from the update.
  return command('post_progress', isTaskRef ? { task: ref, update: update?.trim() ?? '' } : { task: text, update: '' });
}
// Plain text goes to the AI like a voice note; greetings, very short replies and bare links are skipped without an AI call.
const plain = message.body.trim();
if (plain.length <= 2000 && plain.split(/\s+/).length >= 3 && !/^https?:\/\/\S+$/i.test(plain)) {
  return [{ json: { ...base, messageId: message.id, freeText: true } }];
}
return [{ json: { ignored: true } }];

const media = $input.first().json.media;
const audioUrl = media?.url;
if (!/^audio\//i.test(media?.mimetype ?? '') || typeof audioUrl !== 'string' ||
    !/^http:\/\/waha:3000\/api\/files\/[a-zA-Z0-9_@.%-]+(?:\/[a-zA-Z0-9_@.%-]+)*$/.test(audioUrl) ||
    /(?:^|\/)\.{1,2}(?:\/|$)|%2e|%2f|%5c/i.test(audioUrl)) {
  throw new Error('WAHA did not return an authorized audio file');
}
return [{ json: { audioUrl } }];

const content = $input.first().json.choices?.[0]?.message?.content;
if (typeof content !== 'string' || content.length > 5000) throw new Error('Orvix did not return an action');
const out = JSON.parse(content.trim().replace(/^```(?:json)?\s*|\s*```$/gi, ''));
const { chatId, reference, allowedActions } = $('Voice job').first().json;
const field = (value, max, required = true) => {
  if (typeof value !== 'string') throw new Error('Invalid action fields from Orvix');
  const text = value.trim();
  if ((required && !text) || text.length > max) throw new Error('Orvix action fields exceed pilot limits');
  return text;
};
const line = (value) => field(value, 200).replace(/\s+/g, ' ');
const actions = {
  create_task: () => ({ title: line(out.title), description: field(out.description ?? '', 2000, false), tags: [],
    assignees: (Array.isArray(out.assignees) ? out.assignees : []).slice(0, 5).map((a) => field(a, 60)) }),
  save_idea: () => ({ title: line(out.title), description: field(out.summary ?? '', 1000, false), tags: ['idea'] }),
  post_progress: () => ({ task: field(out.task ?? '', 200, false), update: field(out.update, 1000), completed: out.completed === true, inProgress: out.inProgress === true }),
  clarify: () => ({ replyText: field(out.question, 300) }),
  ignore: () => ({}),
};
if (!Object.hasOwn(actions, out?.action)) throw new Error('Unknown action from Orvix');
const fields = actions[out.action]();
if (!['clarify', 'ignore'].includes(out.action) && !allowedActions.includes(out.action)) {
  return [{ json: { chatId, reference, action: 'clarify', replyText: 'That action is not enabled for you in this pilot.' } }];
}
return [{ json: { chatId, reference, action: out.action, ...fields } }];

const job = $input.first().json.body;
if (!job || !/^[a-f0-9]{32}$/.test(job.jobId) || !/^[a-f0-9]{48}$/.test(job.token) || typeof job.chatId !== 'string' || typeof job.messageId !== 'string' || !Array.isArray(job.allowedActions)) throw new Error('Invalid voice job');
return [{ json: job }];

const req = $input.first().json.body;
const LISTS = ["1100310000198006", "1100310000205713"]; // every list this workflow may touch
const ADF_LISTS = []; // lists on the "ClickUp ADF" credential
const deny = () => [{json:{reject:true,response:{statusCode:403,body:{error:'operation_not_allowed'}}}}];
if (!req || !['GET','POST','PUT'].includes(req.method) || typeof req.path !== 'string' || req.path.length > 600) return deny();
const {service, method, path, data} = req;
const task = /^\/task\/([a-zA-Z0-9]{5,20})(?:\/comment)?(?:\?start=\d+&start_id=[a-zA-Z0-9-]+)?$/.exec(path);
if (service === 'clickup') {
 // Every ClickUp call names its list, which picks the credential and bounds what it may touch.
 const scope = req.list;
 if (typeof scope !== 'string' || !LISTS.includes(scope)) return deny();
 const list = /^\/list\/(\d{1,20})\/(member|task(?:\?include_closed=true&page=\d+)?)$/.exec(path);
 const listRead = method === 'GET' && list && list[1] === scope && list[2] !== 'task';
 const create = method === 'POST' && list && list[1] === scope && list[2] === 'task' && data && typeof data.name === 'string' && data.name.length <= 400 && typeof data.markdown_content === 'string' && data.markdown_content.length <= 5000;
 const taskRead = method === 'GET' && task;
 const comment = method === 'POST' && /^\/task\/[a-zA-Z0-9]{5,20}\/comment$/.test(path) && data && typeof data.comment_text === 'string' && data.comment_text.length <= 1200;
 const status = method === 'PUT' && /^\/task\/[a-zA-Z0-9]{5,20}$/.test(path) && data && Object.keys(data).length === 1 && ['complete','in progress'].includes(data.status);
 if (!listRead && !create && !taskRead && !comment && !status) return deny();
 return [{json:{service,method,path,data,taskId:task?.[1],preflight:Boolean(task),list:scope,adf:ADF_LISTS.includes(scope)}}];
}
if (service === 'waha') {
 const send = method === 'POST' && path === '/api/sendText' && data && data.session === 'default' && (["6287729072000@c.us", "108121657733360@lid", "6289637394871@c.us", "37787222962251@lid", "34665845742@c.us", "197048888459509@lid", "15854063775@c.us", "242257764601986@lid", "6281510174878@c.us", "22652362195020@lid", "6282113099490@c.us", "104419446239310@lid", "6281264322144@c.us", "88042584932494@lid", "19173408218@c.us", "25683971563589@lid", "34610210629@c.us", "223837035737316@lid", "5214777041441@c.us", "223209534263432@lid", "6281994770520@c.us", "269663984431135@lid", "6282359361110@c.us", "55692958392522@lid", "6285161912580@c.us", "174440465862739@lid"].includes(data.chatId) || /^[0-9-]{5,40}@g\.us$/.test(data.chatId)) && typeof data.text === 'string' && data.text.length <= 4000;
 const read = method === 'GET' && /^\/api\/default\/chats\/[a-zA-Z0-9@.%-]+\/messages\?limit=50&downloadMedia=false$/.test(path);
 if (!send && !read) return deny();
 return [{json:{service,method,path,data,preflight:false}}];
}
return deny();

const response = $input.first().json;
if (response.statusCode !== 200) return [{json:{reject:true,response}}];
if (response.body?.list?.id !== $('Validate tool request').first().json.list) return [{json:{reject:true,response:{statusCode:403,body:{error:'task_outside_scope'}}}}];
return [{json:$('Validate tool request').first().json}];

const m = $input.first().json;
if (m.fromMe !== false || typeof m.body !== 'string' || !m.body.trim() || m.body.length > 2000) throw new Error('WAHA did not return the text message');
return [{ json: { text: m.body } }];

const job = $('Voice job').first().json;
const text = String((job.freeText ? $('Use message text').first().json.text : $('Transcribe on naspad-server').first().json.text) ?? '');
const NO_ADF_PEOPLE = ["6281264322144@c.us", "88042584932494@lid"]; // people.json noAdf; the worker checks again
// Whisper spells the name several ways: Ama Da Flow, AmaDaFlow, ADF, A.D.F.
const mention = /(^|[^\p{L}\p{N}])(ama\s*da\s*flow|a\.?\s?d\.?\s?f\.?)(?=$|[^\p{L}\p{N}])/iu.test(text);
return [{ json: { adf: mention && !NO_ADF_PEOPLE.includes(job.chatId) } }];
